import{_ as i,a0 as p,w as s,s as n,ao as d,I as l,x as e,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const J=JSON.parse('{"title":"JVM 垃圾回收的工作原理 | LCTT x X-CMD","titleTemplate":false,"description":"JVM 垃圾回收的工作原理 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"JVM 垃圾回收的工作原理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"JVM 垃圾回收的工作原理 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220607 How Garbage Collection works inside a Java Virtual Machine","title":"JVM 垃圾回收的工作原理","tag":"202206","desc":""},"relativePath":"202206/20220607 How Garbage Collection works inside a Java Virtual Machine.md","filePath":"[post].md"}'),u={name:"202206/20220607 How Garbage Collection works inside a Java Virtual Machine.md"};function h(m,a,b,c,g,f){const t=p("Link");return s(),n("div",null,[a[15]||(a[15]=d('<h1 id="jvm-垃圾回收的工作原理" tabindex="-1">JVM 垃圾回收的工作原理 <a class="header-anchor" href="#jvm-垃圾回收的工作原理" aria-label="Permalink to “JVM 垃圾回收的工作原理”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/22/094238qvh45pv2jtpde9td.jpg" alt=""></p><blockquote><p>對於程序員來説，掌握 Java 的內存管理機制並不是必須的，但它能夠幫助你更好地理解 JVM 是如何處理程序中的變量和類實例的。</p></blockquote><p>Java 之所以能夠如此流行，自動 <ruby>垃圾回收<rt>Garbage Collection</rt></ruby>（GC）功不可沒，它也是 Java 最重要的幾個特性之一。在這篇文章中，我將説明為什麼垃圾回收如此重要。本文的主要內容為：自動的分代垃圾回收、JVM 劃分內存的依據，以及 JVM 垃圾回收的工作原理。</p><h3 id="java-內存分配" tabindex="-1">Java 內存分配 <a class="header-anchor" href="#java-內存分配" aria-label="Permalink to “Java 內存分配”">​</a></h3><p>Java 程序的內存空間被劃分為以下四個區域：</p><ol><li><ruby>堆區<rt>Heap</rt></ruby>：對象實例就是在這個區域分配的。不過，當我們聲明一個對象時，堆中不會發生任何內存分配，只是在棧中創建了一個對象的引用而已。</li><li><ruby>棧區<rt>Stack</rt></ruby>：方法、局部變量和類的實例變量就是在這個區域分配的。</li><li><ruby>代碼區<rt>Code</rt></ruby>：這個區域存放了程序的字節碼。</li><li><ruby>靜態區<rt>Static</rt></ruby>：這個區域存放了程序的靜態數據和靜態方法。</li></ol><h3 id="什麼是自動垃圾回收" tabindex="-1">什麼是自動垃圾回收？ <a class="header-anchor" href="#什麼是自動垃圾回收" aria-label="Permalink to “什麼是自動垃圾回收？”">​</a></h3><p>自動垃圾回收是這樣一個過程：首先，堆中的所有對象會被分類為“被引用的”和“未被引用的”；接着，“未被引用的對象”就會被做上標記，以待之後刪除。其中，“被引用的對象”是指程序中的某一部分仍在使用的對象，“未被引用的對象”是指目前沒有正在被使用的對象。</p><p>許多編程語言，例如 C 和 C++，都需要程序員手動管理內存的分配和釋放。在 Java 中，這一過程是通過垃圾回收機制來自動完成的（儘管你也可以在代碼中調用 <code>system.gc();</code> 來手動觸發垃圾回收）。</p><p>垃圾回收的基本步驟如下：</p><h4 id="_1、標記已使用和未使用的對象" tabindex="-1">1、標記已使用和未使用的對象 <a class="header-anchor" href="#_1、標記已使用和未使用的對象" aria-label="Permalink to “1、標記已使用和未使用的對象”">​</a></h4><p>在這一步驟中，已使用和未使用的對象會被分別做上標記。這是一個及其耗時的過程，因為需要掃描內存中的所有對象，才能夠確定它們是否正在被使用。</p><p><img src="https://opensource.com/sites/default/files/2022-06/1Marking.png" alt="標記已使用和未使用的對象"></p><h4 id="_2、掃描-刪除對象" tabindex="-1">2、掃描/刪除對象 <a class="header-anchor" href="#_2、掃描-刪除對象" aria-label="Permalink to “2、掃描/刪除對象”">​</a></h4><p>有兩種不同的掃描和刪除算法：</p><p><strong>簡單刪除（標記清除）</strong>：它的過程很簡單，我們只需要刪除未被引用的對象即可。但是，後續給新對象分配內存就會變得很困難了，因為可用空間被分割成了一塊塊碎片。</p><p><img src="https://opensource.com/sites/default/files/2022-06/2NormalDeletion.png" alt="標記清除的過程"></p><p><strong>刪除壓縮（標記整理）</strong>：除了會刪除未被引用的對象，我們還會壓縮被引用的對象（未被刪除的對象）。這樣以來，新對象的內存分配就相對容易了，並且內存分配的效率也有了提升。</p><p><img src="https://opensource.com/sites/default/files/2022-06/3DeletionwithCompacting.png" alt="標記整理的過程"></p><h3 id="什麼是分代垃圾回收-為什麼需要它" tabindex="-1">什麼是分代垃圾回收，為什麼需要它？ <a class="header-anchor" href="#什麼是分代垃圾回收-為什麼需要它" aria-label="Permalink to “什麼是分代垃圾回收，為什麼需要它？”">​</a></h3><p>正如我們在“掃描刪除”模型中所看到的，一旦對象不斷增長，我們就很難掃描所有未使用的對象以回收內存。不過，有一項實驗性研究指出，在程序執行期間創建的大多數對象，它們的存活時間都很短。</p><p>既然大多數對象的存活時間都很短，那麼我們就可以利用這個事實，從而提升垃圾回收的效率。該怎麼做呢？首先，JVM 將內存劃分為不同的“代”。接着，它將所有的對象都分類到這些內存“代”中，然後對這些“代”分別執行垃圾回收。這就是“分代垃圾回收”。</p><h3 id="堆內存的-代-和分代垃圾回收過程" tabindex="-1">堆內存的“代”和分代垃圾回收過程 <a class="header-anchor" href="#堆內存的-代-和分代垃圾回收過程" aria-label="Permalink to “堆內存的“代”和分代垃圾回收過程”">​</a></h3><p>為了提升垃圾回收中的“標記清除”的效率，JVM 將對內存劃分成以下三個“代”：</p><ul><li><ruby>新生代<rt>Young Generation</rt></ruby></li><li><ruby>老年代<rt>Old Generation</rt></ruby></li><li><ruby>永久代<rt>Permanent Generation</rt></ruby></li></ul><p><img src="https://opensource.com/sites/default/files/2022-06/4Hotspot.png" alt="Hotspot 堆內存結構"></p><p>下面我將介紹每個“代”及其主要特徵。</p><h4 id="新生代" tabindex="-1">新生代 <a class="header-anchor" href="#新生代" aria-label="Permalink to “新生代”">​</a></h4><p>所有創建不久的對象都存放在這裏。新生代被進一步分為以下兩個區域：</p><ol><li><ruby>伊甸區<rt>Eden</rt></ruby>：所有新創建的對象都在此處分配內存。</li><li><ruby>倖存者區<rt>Survivor</rt></ruby>，分為 S0 和 S1：經歷過一次垃圾回收後，仍然存活的對象會被移動到兩個倖存者區中的一個。</li></ol><p><img src="https://opensource.com/sites/default/files/2022-06/5ObjAllocation.png" alt="對象分配"></p><p>在新生代發生的分代垃圾回收被稱為 “<ruby>次要回收<rt>Minor GC</rt></ruby>”（LCTT 譯註：也稱為“<ruby>新生代回收<rt>Young GC</rt></ruby>”）。Minor GC 過程中的每個階段都是“<ruby>停止世界<rt>Stop The World</rt></ruby>”（STW）的，這會導致其他應用程序暫停運行，直到垃圾回收結束。這也是次要回收更快的原因。</p><p>一句話總結：伊甸區存放了所有新創建的對象，當它的可用空間被耗盡，第一次垃圾回收就會被觸發。</p><p><img src="https://opensource.com/sites/default/files/2022-06/6FillingEden.png" alt="填充伊甸區"></p><p>次要回收：在該垃圾回收過程中，所有存活和死亡的對象都會被做上標記。其中，存活對象會被移動到 S0 倖存者區。當所有存活對象都被移動到了 S0，未被引用的對象就會被刪除。</p><p><img src="https://opensource.com/sites/default/files/2022-06/7CopyingRefdObjs.png" alt="拷貝被引用的對象"></p><p>S0 中的對象年齡為 1，因為它們挺過了一次次要回收。此時，伊甸區和 S1 都是空的。</p><p>每當完成清理後，伊甸區就會再次接受新的存活對象。隨着時間的推移，伊甸區和 S0 中的某些對象被宣判死亡（不再被引用），並且伊甸區的可用空間也再次耗盡（填滿了），那麼次要回收 又將再次被觸發。</p><p><img src="https://opensource.com/sites/default/files/2022-06/8ObjAging.png" alt="對象年齡增長"></p><p>這一次，伊甸區和 S0 中的死亡和存活的對象會被做上標記。其中，伊甸區的存活對象會被移動到 S1，並且年齡增加至 1。S0 中的存活對象也會被移動到 S1，並且年齡增加至 2（因為它們挺過了兩次次要回收）。此時，伊甸區和 S0 又是空的了。每次次要回收之後，伊甸區和兩個倖存者區中的一個都會是空的。</p><p>新對象總是在伊甸區被創建，週而復始。當下一次垃圾回收發生時，伊甸區和 S1 都會被清理，它們中的存活對象會被移動到 S0 區。每次次要回收之後，這兩個倖存者區（S0 和 S1）就會交換一次。</p><p><img src="https://opensource.com/sites/default/files/2022-06/9AddlAging.png" alt="額外年齡增長"></p><p>這個過程會一直進行下去，直到某個存活對象的年齡達到了某個閾值，然後它就會被移動到一個叫做“老年代”的地方，這是通過一個叫做“晉升”的過程來完成的。</p><p>使用 <code>-Xmn</code> 選項可以設置新生代的大小。</p><h3 id="老年代" tabindex="-1">老年代 <a class="header-anchor" href="#老年代" aria-label="Permalink to “老年代”">​</a></h3><p>這個區域存放着那些挺過了許多次次要回收，並且達到了某個年齡閾值的對象。</p><p><img src="https://opensource.com/sites/default/files/2022-06/10Promotion.png" alt="晉升"></p><p>在上面這個示例圖表中，晉升的年齡閾值為 8。在老年代發生的垃圾回收被稱為 “<ruby>主要回收<rt>Major GC</rt></ruby>”。（LCTT 譯註：也被稱為“<ruby>全回收<rt>Full GC</rt></ruby>”）</p><p>使用 <code>-Xms</code> 和 <code>-Xmx</code> 選項可以分別設置堆內存大小的初始值和最大值。（LCTT 譯註：結合上面的 <code>-Xmn</code> 選項，就可以間接設置老年代的大小了。）</p><h3 id="永久代" tabindex="-1">永久代 <a class="header-anchor" href="#永久代" aria-label="Permalink to “永久代”">​</a></h3><p>永久代存放着一些元數據，它們與應用程序、Java 標準環境以及 JVM 自用的庫類及其方法相關。JVM 會在運行時，用到了什麼類和方法，就會填充相應的數據。當 JVM 發現有未使用的類，就會卸載或是回收它們，從而為正在使用的類騰出空間。</p><p>使用 <code>-XX:PermGen</code> 和 <code>-XX:MaxPerGen</code> 選項可以分別設置永久代大小的初始值和最大值。</p><h4 id="元空間" tabindex="-1">元空間 <a class="header-anchor" href="#元空間" aria-label="Permalink to “元空間”">​</a></h4><p>Java 8 引入了<ruby>元空間<rt>Metaspace</rt></ruby>，並用它替換了永久代。這麼做的好處是自動調整大小，避免了 <ruby>內存不足<rt>OutOfMemory</rt></ruby>（OOM）錯誤。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>本文討論了各種不同的 JVM 內存“代”，以及它們是如何在分代垃圾回收算法中起作用的。對於程序員來説，掌握 Java 的內存管理機制並不是必須的，但它能夠幫助你更好地理解 JVM 處理程序中的變量和類實例的方式。這種理解使你能夠規劃和排除代碼故障，並理解特定平台固有的潛在限制。</p><p><em>正文配圖來自：Jayashree Huttanagoudar，CC BY-SA 4.0</em></p><hr>',59)),l("p",null,[a[1]||(a[1]=e("via: ",-1)),r(t,{href:"https://opensource.com/article/22/6/garbage-collection-java-virtual-machine"},{default:o(()=>[...a[0]||(a[0]=[e("https://opensource.com/article/22/6/garbage-collection-java-virtual-machine",-1)])]),_:1})]),l("p",null,[a[6]||(a[6]=e("作者：",-1)),r(t,{href:"https://opensource.com/users/jayashree-huttanagoudar"},{default:o(()=>[...a[2]||(a[2]=[e("Jayashree Huttanagoudar",-1)])]),_:1}),a[7]||(a[7]=e(" 選題：",-1)),r(t,{href:"https://github.com/lkxed"},{default:o(()=>[...a[3]||(a[3]=[e("lkxed",-1)])]),_:1}),a[8]||(a[8]=e(" 譯者：",-1)),r(t,{href:"https://github.com/lkxed"},{default:o(()=>[...a[4]||(a[4]=[e("lkxed",-1)])]),_:1}),a[9]||(a[9]=e(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:o(()=>[...a[5]||(a[5]=[e("wxy",-1)])]),_:1})]),l("p",null,[a[12]||(a[12]=e("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:o(()=>[...a[11]||(a[11]=[e("Linux中國",-1)])]),_:1}),a[14]||(a[14]=e(" 榮譽推出",-1))])])}const M=i(u,[["render",h]]);export{J as __pageData,M as default};
